public class Solution {

    static boolean MULTI_TCs = false;
    static String separatorAutoString = "";
    static StringBuilder sb = new StringBuilder(30);
    static BufferedReader reader;
    static PrintWriter writer;

    static class ValueRefPointer<T> {
        T valueNullable;
        boolean hasValue = false;

        public ValueRefPointer<T> IfAbsent(java.util.function.Consumer<ValueRefPointer<T>> init) {
            if (!hasValue) init.accept(this);
            return this;
        }

        public ValueRefPointer<T> UpdateIfAbsent(java.util.function.Supplier<T> calc) {
            if (!hasValue) {
                valueNullable = calc.get();
                hasValue = true;
            }
            return this;
        }

        public ValueRefPointer<T> UpdateCompute(T other, java.util.function.BinaryOperator<T> merge_CHECKED) {
            T ans = other;
            if (hasValue) ans = merge_CHECKED.apply(other, valueNullable);
            valueNullable = ans;
            hasValue = true;
            return this;
        }

        public ValueRefPointer<T> UpdateCompute(T other, java.util.function.BinaryOperator<T> merge_CHECKED, boolean otherHasValue) {
            if (otherHasValue) UpdateCompute(other, merge_CHECKED);
            return this;
        }

        public ValueRefPointer<T> Swap(ValueRefPointer<T> with) {
            T temp = valueNullable;
            boolean tempHas = hasValue;
            valueNullable = with.valueNullable;
            hasValue = with.hasValue;
            with.valueNullable = temp;
            with.hasValue = tempHas;
            return this;
        }

        public ValueRefPointer<T> UpdateCompute(ValueRefPointer<T> other, java.util.function.BinaryOperator<T> merge_CHECKED) {
            if (other.hasValue) UpdateCompute(other.valueNullable, merge_CHECKED);
            return this;
        }

        @Override
        public String toString() {
            return hasValue ? valueNullable.toString() : "null";
        }
